examples.template:
MonarchButton({{trigger}}) { isOpen = true }
    .monarchDialog(
        isPresented: $isOpen,
        title: "Share \u{201C}" + {{itemName}} + "\u{201D}",
        message: {{description}},
        showsCloseButton: true
    ) {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            inviteRow
            Text("People with access").monarchTextStyle(.bodyStrong)
            peopleRows
            Text("General access").monarchTextStyle(.bodyStrong)
            generalAccess
        }
    } footer: {
        EmptyView()
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var invitees: [String] = []
@State private var inviteRole = {{defaultInviteRole}}
@State private var access = {{access.value}}
@State private var roleOf = [{{people.0.email}}: {{people.0.role}}, {{people.1.email}}: {{people.1.role}}]
private let roles = [
    MonarchRoleOption({{roles.0.value}}, title: {{roles.0.label}}),
    MonarchRoleOption({{roles.1.value}}, title: {{roles.1.label}}),
    MonarchRoleOption({{roles.2.value}}, title: {{roles.2.label}}),
]
private let directory = [
    MonarchEntityPickerEntity(id: {{candidates.0.value}}, name: {{candidates.0.label}}, description: {{candidates.0.description}}),
    MonarchEntityPickerEntity(id: {{candidates.1.value}}, name: {{candidates.1.label}}, description: {{candidates.1.description}}),
    MonarchEntityPickerEntity(id: {{candidates.2.value}}, name: {{candidates.2.label}}, description: {{candidates.2.description}}),
]

private var inviteRow: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        MonarchEntityPicker("Invite people", selection: $invitees, entities: directory, prompt: "Name or email")
        HStack(alignment: .center, spacing: theme.spacing.space2) {
            MonarchSelectField(
                "Role for new people",
                selection: $inviteRole,
                options: roles.map { MonarchSelectOption($0.title, value: $0.value) },
                labelVisibility: .hidden
            )
            .frame(width: theme.spacing.space24 * 1.1)
            MonarchButton("Invite", variant: .primary) { invitees = [] }
                .disabled(invitees.isEmpty)
        }
    }
}

private var peopleRows: some View {
    VStack(alignment: .leading, spacing: 0) {
        MonarchMemberRow({{people.0.name}}, url: nil, email: {{people.0.email}}, role: {{people.0.role}}, roles: roles, isSelf: {{people.0.isSelf}})
        MonarchMemberRow(
            {{people.1.name}},
            url: nil,
            email: {{people.1.email}},
            role: roleOf[{{people.1.email}}],
            roles: roles,
            onRoleChange: { roleOf[{{people.1.email}}] = $0 },
            onRemove: {}
        )
        MonarchMemberRow(
            {{people.2.name}},
            url: nil,
            email: {{people.2.email}},
            status: {{people.2.status|case}},
            role: {{people.2.role}},
            roles: roles,
            onRoleChange: { _ in },
            onRemove: {}
        )
    }
}

private var generalAccess: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        MonarchSelectField(
            "Who can open it",
            selection: $access,
            options: [
                MonarchSelectOption({{access.options.0.label}}, value: {{access.options.0.value}}),
                MonarchSelectOption({{access.options.1.label}}, value: {{access.options.1.value}}),
            ],
            helper: access == {{access.options.0.value}} ? {{access.options.0.description}} : {{access.options.1.description}}
        )
        MonarchCopyField("Link", value: {{link}}, isLabelHidden: true)
    }
}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var invitees: [String] = []
@State private var inviteRole = "viewer"
@State private var access = "invited"
@State private var roleOf = ["alex@example.com": "editor", "sam@example.com": "commenter"]
private let roles = [
    MonarchRoleOption("viewer", title: "Viewer"),
    MonarchRoleOption("commenter", title: "Commenter"),
    MonarchRoleOption("editor", title: "Editor"),
]
private let directory = [
    MonarchEntityPickerEntity(id: "u4", name: "Jordan Kim", description: "jordan@example.com"),
    MonarchEntityPickerEntity(id: "u5", name: "Riley Chen", description: "riley@example.com"),
    MonarchEntityPickerEntity(id: "u6", name: "Taylor Brooks", description: "taylor@example.com"),
]

private var inviteRow: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        MonarchEntityPicker("Invite people", selection: $invitees, entities: directory, prompt: "Name or email")
        HStack(alignment: .center, spacing: theme.spacing.space2) {
            MonarchSelectField(
                "Role for new people",
                selection: $inviteRole,
                options: roles.map { MonarchSelectOption($0.title, value: $0.value) },
                labelVisibility: .hidden
            )
            .frame(width: theme.spacing.space24 * 1.1)
            MonarchButton("Invite", variant: .primary) { invitees = [] }
                .disabled(invitees.isEmpty)
        }
    }
}

private var peopleRows: some View {
    VStack(alignment: .leading, spacing: 0) {
        MonarchMemberRow("Alex Morgan", url: nil, email: "alex@example.com", role: "editor", roles: roles, isSelf: true)
        MonarchMemberRow(
            "Sam Lee",
            url: nil,
            email: "sam@example.com",
            role: roleOf["sam@example.com"],
            roles: roles,
            onRoleChange: { roleOf["sam@example.com"] = $0 },
            onRemove: {}
        )
        MonarchMemberRow(
            "Jamie Fox",
            url: nil,
            email: "jamie@example.com",
            status: .invited,
            role: "viewer",
            roles: roles,
            onRoleChange: { _ in },
            onRemove: {}
        )
    }
}

private var generalAccess: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        MonarchSelectField(
            "Who can open it",
            selection: $access,
            options: [
                MonarchSelectOption("Only people invited", value: "invited"),
                MonarchSelectOption("Anyone in the workspace", value: "workspace"),
            ],
            helper: access == "invited" ? "Only the people listed above can open it." : "Everyone in the workspace can find and open it."
        )
        MonarchCopyField("Link", value: "https://example.com/d/quarterly-plan", isLabelHidden: true)
    }
}

